INSERT INTO online_shop.product (name, jyoutai, description, price, stock, maker_id, category_id, image_url) VALUES
-- カーナビゲーション
('7インチワイド液晶カーナビゲーション', '新品', '7インチのワイド液晶を搭載したカーナビゲーションです。大画面で地図が見やすく、運転中も視認性が高いため安全運転をサポートします。Bluetooth対応でスマートフォンと接続すれば音楽再生や通話も可能。さらに最新地図の更新が無料で提供されるため、常に正確なルート案内を受けられます。長距離ドライブから日常の買い物まで、幅広い用途に活用できる便利な一台です。', 35000.00, 8, 1, 1, 'https://t4.ftcdn.net/jpg/06/13/33/59/240_F_613335941_P2VoWdeKA9bDrv5Nk7Z5Ib0bTHyzVOCQ.jpg'),
('Bluetooth対応カーナビゲーション', '新品', 'スマートフォンと簡単にBluetooth接続できるカーナビです。音声案内機能付きで運転中もハンズフリーで操作可能。ルート検索や目的地設定がスムーズで、渋滞情報やリアルタイム交通情報にも対応しています。7インチの液晶画面は視認性が高く、運転中のストレスを軽減。地図更新も無料で提供されるため、長期利用でも安心です。初心者からベテランドライバーまで使いやすい設計になっています。', 42000.00, 6, 2, 1, NULL),
('地図更新無料カーナビゲーション', '新品', '最新地図データの更新が無料で提供されるカーナビゲーションです。7インチ液晶で画面が広く、交差点や曲がり角もはっきり表示されるため運転中の安心感が高まります。Bluetooth対応でスマホとの連携も可能。音声案内やルート検索もスムーズで、長距離ドライブや初めての道でも迷わず目的地へ到着できます。安全性と利便性を両立させた多機能モデルです。', 50000.00, 4, 3, 1, NULL),

-- ドライブレコーダー
('フルHD前方録画ドライブレコーダー', '新品', 'フルHD画質対応のドライブレコーダーで、前方視界を鮮明に録画します。高感度カメラを搭載しているため、夜間やトンネル内でもくっきりと映像を記録可能です。衝撃検知機能や自動録画機能も備えており、事故やトラブルの際の証拠として活用できます。コンパクトで取り付けも簡単、運転中に邪魔にならない設計です。安全運転のサポートだけでなく、万が一のトラブル対応にも安心の一台です。', 9800.00, 15, 4, 2, NULL),
('前後2カメラ搭載ドライブレコーダー', '新品', '前後2カメラ搭載のドライブレコーダーです。前方と後方の両方を録画できるため、事故や接触時の証拠映像として非常に有用です。駐車監視や衝撃検知機能も備え、駐車中のトラブルや当て逃げにも対応可能。夜間映像も鮮明で、車両周辺の状況をしっかり記録します。設置も簡単で、運転中に視界を妨げず安心して使用できます。安全性と利便性を兼ね備えた高性能モデルです。', 15000.00, 10, 2, 2, NULL),
('駐車監視機能付き高性能ドライブレコーダー', '新品', '駐車監視機能を備えた高性能ドライブレコーダーです。車両が駐車中でも衝撃を感知すると自動で録画を開始し、事故や盗難の証拠映像として活用できます。フルHD画質で映像は鮮明、前方視界も広く安全運転をサポート。取り付けも簡単で、初心者でも安心して使用可能です。夜間や暗所でも高感度カメラでしっかり撮影でき、万が一のトラブルにも備えられる安心設計です。', 20000.00, 5, 5, 2, NULL),

-- スマホホルダー
('360度回転式車載スマホホルダー', '新品', '360度回転可能な車載スマホホルダーです。運転中のナビアプリや通話、動画視聴に便利で、車内のエアコン吹き出し口に簡単取り付けできます。角度調整も自由にでき、iPhoneやAndroidなど幅広い機種に対応。しっかり固定できるので走行中の振動や揺れにも耐え、安心して使用可能です。コンパクト設計で視界を妨げず、長時間の運転でも快適に利用できます。', 1200.00, 50, 6, 3, NULL),
('エアコン吹き出し口対応スマホスタンド', '新品', 'エアコン吹き出し口に簡単に取り付け可能なスマホスタンドです。360度回転と角度調整機能付きで、運転中でも画面が見やすく操作もスムーズ。iPhoneやAndroidなど様々なスマートフォンに対応しており、ナビアプリや動画視聴にも最適。安定した固定力で走行中の振動に強く、長距離ドライブでも安心。コンパクトながら使いやすさを追求した車載アクセサリーです。', 1800.00, 30, 7, 3, NULL);